"created_at\")\n\n  user      User  @relation(\"RoleRequestRequester\", fields: [userId], references: [id], onDelete: Cascade)\n  decidedBy User? @relation(\"RoleRequestDecider\", fields: [decidedById], references: [id], onDelete: SetNull)\n\n  @@index([status])\n  @@index([userId])\n  @@map(\"role_requests\")\n}\n\n// --------------------------------------------------------------------- staff\n\nmodel StaffMember {\n  id String @id @default(uuid()) @db.Uuid\n\n  systemId      String   @unique @map(\"system_id\")\n  fullName      String   @map(\"full_name\")\n  preferredName String   @map(\"preferred_name\")\n  pronouns      String\n  title         String\n  departments   String[]\n\n  email          String @unique\n  phoneExtension String @map(\"phone_extension\")\n  directPhone    String @map(\"direct_phone\")\n\n  shiftPreference ShiftPreference @map(\"shift_preference\")\n  /// `ShiftRotation[]` — label / days / hours.\n  shiftRotations  Json            @map(\"shift_rotations\")\n\n  avatarUrl String? @map(\"avatar_url\")\n\n  @@index([fullName])\n  @@map(\"staff_members\")\n}\n\n// ------------------------------------------------------------------- logging\n\nmodel SearchLog {\n  id String @id @default(uuid()) @db.Uuid\n\n  query       String\n  resultCount Int           @map(\"result_count\")\n  surface     SearchSurface\n  createdAt   DateTime      @default(now()) @map(\"created_at\")\n\n  @@index([createdAt(sort: Desc)])\n  @@index([resultCount])\n  @@map(\"search_logs\")\n}\n",
